    return bytes([3 if ecn else 2])+v(largest)+v(rnd.randrange(0,100))+v(len(pairs)+1)+v(first)+b''.join(v(g)+v(r) for g,r in pairs)+(b''.join(v(x) for x in ecn) if ecn else b'')
